  and is_deleted = 0

    and type = #{type}

order by id

mapper.update:
update device_satellite
set is_deleted = 0, update_time = current_timestamp
where task_id = #{taskId} and id = #{id}

update device_satellite set is_deleted = 1, update_time = current_timestamp where is_deleted = 0
and task_id = #{taskId} and id = #{deviceSatelliteId}
and 1 = 0
